-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "deDE" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.priest.dps.Name"] = "Schaden"
L["rm.era.priest.dps.Description"] = "Schaden von Stufe 1 bis 60 und der Priester-Standard, wann immer die integrierte Heilerrotation nicht greift (solo, Schatten oder noch keine Talente). Schattengestalt, sobald erlernt; vor einem Pull solo ein Schild, dann Heiliges Feuer (ohne Schattengestalt), Gedankenschlag oder Göttliche Pein. Schattenwort: Schmerz einmal pro Ziel, das lange genug lebt, Gedankenschlag bei Abklingzeit-Ende, Gedankenschinden als Füller (Göttliche Pein und Heilige Nova, bevor Sie es haben) und der Zauberstab auf ein sterbendes Ziel oder bei knappem Mana im Solospiel. Vampirumarmung und Verschlingende Seuche bei langen Kämpfen, nie in Schlachtzügen. Erinnerungen: Inneres Feuer, Seelenstärke, Volks-Stärkungszauber, Innerer Fokus mit Gedankenschlag, Psychischer Schrei, wenn zwei Gegner Sie bei halber Gesundheit erreichen, Verblassen, wenn Ihr Ziel Sie angreift, Verzweifeltes Gebet. Zielwahl, DoTs auf mehreren Zielen und Herabstufen von Rängen bleiben Ihnen überlassen."
L["rm.era.priest.dps.simulator.Name"] = "Schaden (Simulation, Untote im Schlachtzug)"
L["rm.era.priest.dps.simulator.Description"] = "Die empfohlene Schadenspriorität mit der Schlachtzugswahl von Simulation für untote Priester: Innerer Fokus wird für Verschlingende Seuche statt Gedankenschlag eingesetzt, und Verschlingende Seuche wird auch in Schlachtzügen gewirkt, nutzen Sie sie also nur, wo Ihr Schlachtzug freie Plätze für Schwächungszauber hat. Keine Vampirumarmung. Eine Alternative zur empfohlenen integrierten Schadensrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität."
L["rm.era.priest.dps.warcrafttavern.Name"] = "Schaden (Warcraft Tavern, Zauberstab-Ökonomie)"
L["rm.era.priest.dps.warcrafttavern.Description"] = "Der Leveling-Stil von Warcraft Tavern mit wenig Pausen, eine Alternative zur empfohlenen integrierten Schadensrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Solo: Gedankenschlag zum Ziehen, einmal Schattenwort: Schmerz, erneut Gedankenschlag nur, solange das Ziel über 30 % liegt, und Ihr Zauberstab zwischen den Gedankenschlägen statt Göttlicher Pein oder Gedankenschinden. Kein automatischer Schild vor Pulls. In einer Gruppe: Schattenwort: Schmerz, Gedankenschlag, Gedankenschinden. Dieselben Erinnerungen wie die empfohlene integrierte Rotation."
L["rm.era.priest.healer.Name"] = "Heiler"
L["rm.era.priest.healer.Description"] = "Gewählt in einer Gruppe, wenn Heilig oder Disziplin Ihr Haupttalentbaum ist. Heilt die freundliche Einheit, die Sie anvisieren: Machtwort: Schild unter 30 %, Blitzheilung unter 40 %, Bannungen, Gebet der Heilung, wenn drei Ihrer Gruppe verletzt sind, Große Heilung (Heilen oder Geringes Heilen, bevor Sie sie erlernen) unter halber Gesundheit, Erneuerung in Bewegung oder bei leichtem Schaden, dann Heilen Rang 3 als effizientes Auffüllen. Außerhalb des Kampfes bietet sie Seelenstärke auf Ihr Ziel an. Ein anvisierter Gegner erhält Schattenwort: Schmerz und Göttliche Pein. Erinnerungen: Inneres Feuer, Seelenstärke, Göttlicher Willen, Innerer Fokus, Verzweifeltes Gebet; Seele der Macht ist standardmäßig deaktiviert. Wen Sie heilen und das Herabstufen von Rängen bleiben Ihnen überlassen."
L["rm.forever.priest.dps.Name"] = "Schatten und Solo-Schaden"
L["rm.forever.priest.dps.Description"] = "Schatten und das Solospiel jedes Priesters, von Stufe 1 bis 60; der Forever-Priester-Standard. Zieht mit Machtwort: Schild (solo) und Gedankenschlag (Heiliges Feuer für Heilig und Disziplin, Heilige Pein vor Gedankenschlag). Dann Schattengestalt, sobald erlernt, Ihr eigenes Schattenwort: Schmerz und Ihre Verschlingende Seuche, Gedankenschlag, Heiliges Feuer in Sühne für Disziplin, Gedankenschinden in Schattengestalt; solo vor Schattengestalt Heilige Nova gegen drei Gegner mit Heiliger Zweck, dann der Zauberstab (Heilige Pein ohne einen). In Bewegung: Schmerz, Seuche. Erinnerungen: Inneres Feuer, Seelenstärke, Göttlicher Willen, Volks-Stärkungszauber, Vampirumarmung, Innerer Fokus, Stille, Elunes Licht; Psychischer Schrei ist standardmäßig deaktiviert. Gesundheit und Mana sind für Addons unter Forever verborgen, daher entscheiden Sie selbst über das Erledigen mit Schattenwort: Tod, Selbstheilung und Dunkles Opfer. Erstellt aus Beta-Leitfäden für Stufe 30; das Spiel in Schattengestalt folgt Mobalytics."
L["rm.forever.priest.dps.mobalytics.Name"] = "DoT- und Zauberstab-Leveling (Mobalytics)"
L["rm.forever.priest.dps.mobalytics.Description"] = "Levelstil von Mobalytics, eine Alternative zur empfohlenen integrierten Schattenrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Gedankenschlag und Heiliges Feuer nur gegen zähe Gegner (Elitegegner oder zwei Stufen über Ihnen), Ihr eigenes Schattenwort: Schmerz und Ihre Verschlingende Seuche, dann der Zauberstab (Heilige Pein ohne einen). Ab Schattengestalt: Gedankenschlag, Schmerz, Seuche, Gedankenschinden. Schild und Erneuerung auf sich selbst zwischen Pulls, Krankheit heilen auf sich selbst. Gesundheit und Mana sind für Addons unter Forever verborgen, daher bleibt die Selbstheilung Ihnen überlassen. Grassierender Schmerz über mehrere Gegner bleibt Ihnen überlassen."
L["rm.forever.priest.healer.Name"] = "Disziplin- und Heilig-Heilung"
L["rm.forever.priest.healer.Description"] = "Gruppenheilung, sobald Disziplin oder Heilig Ihr Haupttalentbaum ist und Sie Schattengestalt nicht beherrschen. Heilt Ihr aktuelles freundliches Ziel: vor dem Pull Machtwort: Schild, Gebet der Besserung und Erneuerung; Magiebannung und Krankheit aufheben oder Krankheit heilen; Gebet der Besserung; Heilige Nova bei Heiliger Zweck; Sühne; Erneuerung, wenn sie fehlt; Heilen (davor Geringes Heilen). Gegen einen Gegner: Schattenwort: Schmerz, Heiliges Feuer, Sühne, Heilige Pein, Zauberstab. Erinnerungen: Inneres Feuer, Seelenstärke, Göttlicher Willen, Seele der Macht auf einen anderen Spieler, Innerer Fokus im Kampf und die Volkszauber. Gesundheit und Mana sind für Addons unter Forever verborgen, daher ist das Ziel, das Sie wählen, der einzige Hinweis darauf, wer Heilung braucht; Notheilungen, Gebet der Heilung, Verbindende Heilung, Große Heilung und Blitzheilung, Verzweifeltes Gebet und Dunkles Opfer bleiben Ihnen überlassen. Wen Sie heilen und den Rang wählen Sie; ein Disziplin-Heiler vor Sühne (20–29) wählt diese Rotation von Hand aus."
L["rm.mop.priest.discipline.Name"] = "Empfohlen"
L["rm.mop.priest.discipline.Description"] = "Disziplin-Heilung von Stufe 10 bis 90, gewählt in der Spezialisierung Disziplin. Visieren Sie einen Verbündeten an, um ihn zu heilen: Machtwort: Schild, wenn er wenig Gesundheit hat, vor dem Pull und etwa alle 12 Sekunden für Euphorie; Blitzheilung bei Woge des Lichts; Sühne; Blitzheilung, wenn er sehr wenig Gesundheit hat; Verbindende Heilung, wenn Sie beide verletzt sind; Gebet der Besserung; Gebet der Heilung und Ihr Talent der Stufe 6, wenn drei Verbündete verletzt sind; Große Heilung; Erneuerung in Bewegung; Heilung zum Auffüllen. Während Geisthülle schlägt sie Gebet der Heilung oder Große Heilung vor. Visieren Sie einen Gegner an, um über Abbitte zu heilen: Sühne, Machtwort: Trost oder Heiliges Feuer, Ihr Talent der Stufe 6 gegen Gruppen, Schattenwort: Schmerz solo, Heilige Pein. Erinnerungen: Inneres Feuer, Seelenstärke, Erzengel bei fünf Stapeln Prediger, Innerer Fokus, Schmerzunterdrückung auf ein sterbendes Ziel, Schattengeist oder Geistbeuger für Mana, Seele der Macht, Verzweifeltes Gebet. Ihnen überlassen: wen Sie heilen, das Timing von Geisthülle (eine Erinnerung, die Sie aktivieren können), Machtwort: Barriere, Leerenverschiebung und Stapel von Barmherzigkeit auf dem Tank."
L["rm.mop.priest.holy.Name"] = "Empfohlen"
L["rm.mop.priest.holy.Description"] = "Heilig-Heilung von Stufe 10 bis 90, gewählt in der Spezialisierung Heilig. Visieren Sie einen Verbündeten an, um ihn zu heilen: Segenswort: Epiphanie in Chakra: Epiphanie; Machtwort: Schild nur, wenn er kurz vor dem Tod steht; Blitzheilung bei Woge des Lichts; Gebet der Besserung; Blitzheilung bei sehr wenig Gesundheit; Verbindende Heilung, wenn Sie beide verletzt sind; in einer Gruppe mit drei verletzten Verbündeten Kreis der Heilung, Segenswort: Refugium in Chakra: Refugium, Ihr Talent der Stufe 6 und Gebet der Heilung; Erneuerung; Große Heilung bei wenig Gesundheit oder bei zwei Stapeln Glücksfall; Heilung. Visieren Sie einen Gegner an, um Schaden zu verursachen: Segenswort: Züchtigung, Machtwort: Trost oder Heiliges Feuer, Schattenwort: Schmerz solo, Ihr Talent der Stufe 6 gegen Gruppen, Heilige Pein. Ein leeres Chakra wird für Sie gefüllt (Refugium im Schlachtzug, Epiphanie in einer Gruppe, Züchtigung solo) und nie gewechselt. Erinnerungen: Inneres Feuer, Seelenstärke, Schutzgeist auf ein sterbendes Ziel, Gotteshymne, wenn fünf Verbündete schwer verletzt sind, Schattengeist oder Geistbeuger für Mana, Seele der Macht, Verzweifeltes Gebet. Ihnen überlassen: wen Sie heilen, das Platzieren von Segenswort: Refugium, Lichtbrunnen und Leerenverschiebung."
L["rm.mop.priest.holy.icyveins.Name"] = "Notfallheilungen zuletzt (Icy Veins)"
L["rm.mop.priest.holy.icyveins.Description"] = "Standardmäßig deaktiviert. Die Heilig-Reihenfolge von Icy Veins, gewählt nach Ihrem Chakra. In Chakra: Refugium: Segenswort: Refugium, wenn drei Verbündete verletzt sind, Erneuerung, Kreis der Heilung, Gebet der Besserung, Gebet der Heilung, dann Verbindende Heilung und Blitzheilung nur im Notfall. Sonst: Erneuerung, Segenswort: Epiphanie, Gebet der Besserung, Große Heilung, Heilung, Verbindende Heilung, Blitzheilung, Machtwort: Schild zuletzt und Blitzheilung als Füller, bevor Sie Heilung erlernen. Dieselbe Umschaltung, dieselben Erinnerungen und dieselbe Schadensliste wie die empfohlene integrierte Heilig-Rotation; aktivieren Sie sie und deaktivieren Sie die empfohlene, um sie zu verwenden."
L["rm.mop.priest.shadow.Name"] = "Empfohlen"
L["rm.mop.priest.shadow.Description"] = "Schattenschaden von Stufe 10 bis 90, gewählt in der Spezialisierung Schatten. Eröffnet mit Gedankenstachel, Gedankenschlag oder Ihren DoTs. Verschlingende Seuche bei drei Schattenkugeln (wenn Gedankenschlag bereit oder noch sechs Sekunden entfernt ist), Gedankenschlag, Schattenwort: Tod unter 20 % Gesundheit, Gedankenschinden, solange Ihre Verschlingende Seuche aktiv ist, wenn Sie Trost und Wahnsinn gewählt haben, Schattenwort: Schmerz und Vampirberührung kurz vor dem Ende auf einem Ziel erneuert, das lange genug lebt, Gedankenstachel bei Woge der Dunkelheit, Strahlenkranz, Kaskade oder Göttlicher Stern in ihrer besten Reichweite, dann Gedankenschinden. Ein Gedankenschinden wird für Gedankenschlag oder Schattenwort: Tod oder nach seinem zweiten Tick abgebrochen; andere Kanalisierungen werden nie unterbrochen. In Bewegung schlägt sie nur Spontanzauber vor. Gegen fünf oder mehr Gegner: Ihr Talent der Stufe 6, DoTs auf Ihrem Ziel und Gedankenexplosion. Erinnerungen: Schattengestalt, Inneres Feuer, Seelenstärke, Stille bei unterbrechbaren Zaubern, Schattengeist oder Geistbeuger und Seele der Macht bei langen Kämpfen, Vampirumarmung, Verzweifeltes Gebet und Dispersion bei niedriger Gesundheit. Ihnen überlassen: DoTs auf anderen Zielen und wo Gedankenexplosion landet."
L["rm.mop.priest.shadow.warcrafttavern.Name"] = "Ohne Wahnsinn-Priorität (Warcraft Tavern)"
L["rm.mop.priest.shadow.warcrafttavern.Description"] = "Standardmäßig deaktiviert. Die Schatten-Reihenfolge von Warcraft Tavern: Verschlingende Seuche bei drei Schattenkugeln, Schattenwort: Tod unter 20 %, Gedankenschlag, Vampirberührung, Schattenwort: Schmerz, Gedankenstachel bei Woge der Dunkelheit, Ihr Talent der Stufe 6, Gedankenschinden. Anders als die empfohlene integrierte Schattenrotation zieht sie Gedankenschinden während Verschlingender Seuche nie vor und hält Verschlingende Seuche nicht für Gedankenschlag zurück. Dieselben Schritte für Eröffnung, Bewegung, Gruppen und Erinnerungen; aktivieren Sie sie und deaktivieren Sie die empfohlene, um sie zu verwenden."
L["rm.mop.priest.unspecialized.Name"] = "Ohne Spezialisierung"
L["rm.mop.priest.unspecialized.Description"] = "Für Stufe 1 bis 9 oder jeden Priester, der noch keine Spezialisierung gewählt hat. Gegen einen Gegner: Schattenwort: Schmerz, wenn er lange genug lebt, dann Heilige Pein. Auf einen Verbündeten: Blitzheilung, wenn er wenig Gesundheit hat, sonst Machtwort: Schild. Erinnerungen: Inneres Feuer und ein Schild auf Ihnen selbst, wenn Sie solo und verletzt sind. Die Wahl einer Spezialisierung auf Stufe 10 wechselt zu deren eigener integrierter Rotation."
L["rm.retail.priest.discipline.Name"] = "Abbitte (Icy Veins)"
L["rm.retail.priest.discipline.Description"] = "Disziplin in Midnight, als Referenz: Blizzards Kampfassistent deckt keine Heiler ab, das Spiel verbirgt im Kampf die Gesundheit aller, und Rotation Master wählt einen Zauber, kein Ziel, daher spielt diese Rotation den Schaden, der über Abbitte heilt, und überlässt Ihnen die Entscheidung, wen Sie heilen. Bei einem freundlichen Ziel: Machtwort: Schild (Leerenschild), Sühne, Blitzheilung. Bei einem Gegner: Schattenwort: Schmerz, wenn Sie es 12 Sekunden lang nicht gewirkt haben, Gedankenschlag, Sühne, Schild, Schattenwort: Tod, Leerenschlag, Heilige Pein. Erinnerungen im Kampf: Machtwort: Glanz, Prediger, Ultimative Bußfertigkeit, Schmerzunterdrückung auf einem freundlichen Ziel; Seelenstärke zwischen den Kämpfen. Verzweifeltes Gebet bleibt Ihnen überlassen. Das Timing von Schlachtzugs-Ramps vor großem Schaden liegt bei Ihnen."
L["rm.retail.priest.discipline.wowhead.Name"] = "Schattenwort: Tod zuerst, Referenz (Wowhead)"
L["rm.retail.priest.discipline.wowhead.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Orakel-Reihenfolge von Wowhead für Saison 1, die Schattenwort: Schmerz aufrechterhält, indem sie den Schwächungszauber ausliest, den Midnight im Kampf verbirgt. Schattenwort: Schmerz, Schattenwort: Tod bei Abklingzeit-Ende, Sühne, Gedankenschlag, Heilige Pein; bei einem freundlichen Ziel zuerst Sühne. Dieselben Erinnerungen wie die integrierte Rotation nach Icy Veins."
L["rm.retail.priest.holy.Name"] = "Icy Veins"
L["rm.retail.priest.holy.Description"] = "Heilig in Midnight, als Referenz: Das Spiel verbirgt im Kampf die Gesundheit aller, und Rotation Master wählt einen Zauber, kein Ziel, daher hält diese Rotation Ihre Segensworte, Gebet der Besserung und Procs auf jedem Ziel, das Sie anvisieren, in Gang und überlässt Ihnen die Triage. Bei einem freundlichen Ziel: Segenswort: Heiligung, Segenswort: Epiphanie, Gebet der Besserung, Gebet der Heilung mit Woge des Lichts, Segnung, Gebet der Heilung mit Lichtweber, Blitzheilung mit Woge des Lichts, Gebet der Heilung in einer Gruppe, Heilige Nova in Bewegung, Blitzheilung. Bei einem Gegner: Segenswort: Züchtigung, Heiliges Feuer, Heilige Nova in Bewegung, Heilige Pein. Erinnerungen: Apotheose, Gotteshymne und Strahlenkranz im Kampf, Schutzgeist auf einem freundlichen Ziel (die Gesundheit ist unter Retail verborgen, daher bleibt es Ihnen überlassen, ob es kurz vor dem Tod steht), Seelenstärke. Verzweifeltes Gebet bleibt Ihnen überlassen."
L["rm.retail.priest.initial.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.priest.initial.Description"] = "Empfohlen, bevor Sie eine Spezialisierung wählen (solange das Spiel die Anfangsspezialisierung des Priesters meldet). Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben die Erinnerungen, die jede integrierte Priester-Rotation teilt, jeweils sobald Sie den Zauber kennen. Wenn Sie auf Stufe 10 eine Spezialisierung wählen, übernehmen die integrierten Rotationen dieser Spezialisierung."
L["rm.retail.priest.shadow.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.priest.shadow.Description"] = "Empfohlen für Schatten in Midnight. Im Kampf verbirgt das Spiel nun Ihre DoTs, Stärkungszauber, Abklingzeiten und Gesundheit vor Addons, daher zeigt diese Rotation den eigenen Vorschlag von Blizzards Kampfassistent (die Ein-Tasten-Rotation, die Ihre DoTs, Schattengestalt und Leerengestalt aufrechterhält und Gedankenschinden zu Ende kanalisieren lässt) und pausiert, während Sie wirken oder kein Gegner anvisiert ist. Erinnerungen an das, was er auslässt: Seele der Macht in den 20 Sekunden, nachdem Sie Leerengestalt gewirkt haben, Schattengestalt und Machtwort: Seelenstärke zwischen den Kämpfen, Stille bei einem unterbrechbaren Zauber (sie leuchtet nur dort auf, wo das Spiel den Zauber auslesen lässt). Die Gesundheit ist unter Retail verborgen, daher bleibt Verzweifeltes Gebet Ihnen überlassen."
L["rm.retail.priest.shadow.icyveins.Name"] = "Referenz (Icy Veins)"
L["rm.retail.priest.shadow.icyveins.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Reihenfolge von Icy Veins und SimulationCraft liest DoT-Timer, den Effekt Wahnsinn und Leerengestalt, die Midnight im Kampf verbirgt; Wahnsinn (die Ressource) und Gesundheit sind unter Retail verborgen, daher bleiben Schattenwort: Wahnsinn am Wahnsinn-Maximum, das Erledigen mit Schattenwort: Tod und Verzweifeltes Gebet Ihnen überlassen. Vampirberührung vor dem Pull; Tentakelschlag, um Vampirberührung aufzubringen; Vampirberührung und Schattenwort: Schmerz in ihren letzten 30 % erneuert; Schattenwort: Wahnsinn, wenn es ausläuft oder während Leerengestalt; Leerenschlag während des Effekts Wahnsinn; Tentakelschlag bei zwei Aufladungen; Leerenstrom; Gedankenschlag; Tentakelschlag; Gedankenschinden: Wahnsinn während des Effekts Wahnsinn; Leerensalve; Schattenwort: Tod und Schattenwort: Schmerz in Bewegung; Gedankenschinden, abgebrochen, sobald Gedankenschlag bereit ist. Erinnerungen: Strahlenkranz, Leerengestalt mit beiden aktiven DoTs, Seele der Macht während Leerengestalt."
L["rm.sod.priest.dps.Name"] = "Schaden (SoD)"
L["rm.sod.priest.dps.Description"] = "Schaden auf Realms der Saison der Entdeckungen von Stufe 1 bis 60 mit den Runen, die Sie graviert haben. Schattengestalt; Vampirberührung oder Gedankenschlag zum Ziehen (Sühne, Heiliges Feuer oder Göttliche Pein vor Schattengestalt). Pest der Leere, Schattenwort: Schmerz und Vampirberührung aufrechterhalten (nur ohne die Rune „Pain and Suffering“ gegen Ende erneuert), Gedankenschlag bei Abklingzeit-Ende, Gedankenschinden bei Gesichter schmelzen, Schattenwort: Tod, solange Sie über halber Gesundheit sind, dann Gedankenstachel als Füller oder Gedankenschinden mit dem Sechsteile-Set aus Phase 8. Zone der Leere und Gedankenbrand gegen vier oder mehr Gegner. Der Zauberstab auf ein sterbendes Ziel im Solospiel. Erinnerungen: Inneres Feuer, Seelenstärke, Homunculi, Schattengeist, Auge der Leere und Dispersion, Innerer Fokus, Psychischer Schrei, Verblassen, Verzweifeltes Gebet."
L["rm.sod.priest.dps.wowhead.Name"] = "Schaden (SoD, Wowhead, Stapel von Gedankenstachel)"
L["rm.sod.priest.dps.wowhead.Description"] = "Die Spielweise von Wowhead und Warcraft Tavern für die Saison der Entdeckungen, eine Alternative zur empfohlenen integrierten Schadensrotation der Saison der Entdeckungen, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Gedankenschlag wartet auf drei Ihrer Stapel von Gedankenstachel auf dem Ziel (bis Sie Gedankenstachel gravieren, wird er normal gewirkt), Gedankenschinden nur bei Gesichter schmelzen, Gedankenstachel als Füller. Alles andere entspricht der empfohlenen integrierten Rotation."
L["rm.sod.priest.healer.Name"] = "Heiler (SoD)"
L["rm.sod.priest.healer.Description"] = "Gewählt auf Realms der Saison der Entdeckungen in einer Gruppe, wenn Heilig oder Disziplin Ihr Haupttalentbaum ist; folgt Icy Veins. Heilt die freundliche Einheit, die Sie anvisieren: Gebet der Besserung vor dem Pull und sobald bereit, Schild unter halber Gesundheit, Sühne, sofortige Blitzheilung bei Woge des Lichts, Blitzheilung im Notfall, Bannungen, Kreis der Heilung und Gebet der Heilung, wenn drei Ihrer Gruppe verletzt sind, Große Heilung unter halber Gesundheit, Erneuerung in Bewegung oder bei leichtem Schaden, dann Heilen. Ein anvisierter Gegner erhält Schmerz, Pest der Leere, Sühne, Heiliges Feuer und Göttliche Pein. Zu den Erinnerungen gehören Schattengeist, Schmerzunterdrückung auf ein sterbendes Ziel, Machtwort: Barriere und Geist des Erlösers, wenn die Gruppe verletzt ist."
L["rm.sod.priest.healer.warcrafttavern.Name"] = "Heiler (SoD, Warcraft Tavern)"
L["rm.sod.priest.healer.warcrafttavern.Description"] = "Die Glücksfall-Schleife von Warcraft Tavern, ausgelegt auf Glücksfall und Seelenwehr, eine Alternative zur empfohlenen integrierten Heilerrotation der Saison der Entdeckungen, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Gebet der Besserung bei Abklingzeit-Ende, Schild auf Ihr Ziel, wann immer es einen erhalten kann (mit eingravierter Rune Seelenwehr; sonst unter halber Gesundheit), Sühne bei hohem Schaden, Kreis der Heilung bei drei Verletzten, Große Heilung oder Gebet der Heilung bei drei Stapeln Glücksfall, Erneuerung bei geringem Schaden und Blitzheilung bei kleinen Verletzungen, um die Stapel aufzubauen (mit eingravierter Rune Glücksfall; sonst unter 30 %)."
L["rm.tbc.priest.dps.icyveins.Name"] = "Schaden (Icy Veins)"
L["rm.tbc.priest.dps.icyveins.Description"] = "Schaden von Stufe 1 bis 70, verwendet, wann immer die integrierte Heilerrotation nicht greift. Anfangs Göttliche Pein und Zauberstab, dann Gedankenschlag, Schattenwort: Schmerz, Gedankenschinden, Schattengestalt, Vampirberührung und Schattenwort: Tod, sobald Sie sie erlernen; DoTs vor Gedankenschlag; ein sterbendes Ziel wird beim Solospiel mit dem Zauberstab erledigt. Heilig- und Disziplin-Priester beim Questen erhalten Heiliges Feuer und Göttliche Pein. Erinnerungen: Inneres Feuer, Seelenstärke, Volks-Stärkungszauber, Innerer Fokus, Schattengeist. Ein Gedankenschinden nach seinem ersten Tick wird für einen bereiten Gedankenschlag abgebrochen, oder für Schattenwort: Tod über halber Gesundheit. Schilde und Heilung bleiben Ihnen überlassen."
L["rm.tbc.priest.dps.wowhead.Name"] = "Schaden (Wowhead)"
L["rm.tbc.priest.dps.wowhead.Description"] = "Schaden nach den Leitfäden von Wowhead, eine Alternative zur empfohlenen integrierten Schadensrotation nach Icy Veins, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Gedankenschlag eröffnet und kommt vor dem Erneuern der DoTs, Vampirumarmung nur, wenn Ihre Gesundheit sinkt, und ein sterbendes Ziel erhält Zauber statt des Zauberstabs. Ansonsten wie die empfohlene integrierte Rotation."
L["rm.tbc.priest.healer.icyveins.Name"] = "Heiler (Icy Veins)"
L["rm.tbc.priest.healer.icyveins.Description"] = "Heilung in der Reihenfolge von Icy Veins: Schild, Bannungen, Verbindende Heilung, Erneuerung, Blitzheilung, Große Heilung (beliebiger Rang), Gruppenheilungen und zuletzt Gebet der Besserung. Wen Sie heilen, entscheiden Sie. Eine Alternative zur empfohlenen integrierten Heilerrotation nach Wowhead, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität."
L["rm.tbc.priest.healer.wowhead.Name"] = "Heiler (Wowhead)"
L["rm.tbc.priest.healer.wowhead.Description"] = "Heilung in einer Gruppe, wenn Heilig oder Disziplin Ihr Haupttalentbaum ist. Sie berät zu der freundlichen Einheit, die Sie anvisieren; wen Sie heilen, entscheiden Sie. Gebet der Besserung vor Pulls und sobald bereit, Erneuerung, Machtwort: Schild im Notfall, Bannungen, Kreis der Heilung oder Gebet der Heilung bei Gruppenschaden, Verbindende Heilung, Blitzheilung und Große Heilung sowie Große Heilung Rang 1 als günstiges Auffüllen. Mit einem anvisierten Gegner bietet sie leichten Schaden an."
